package com.wardk.meeteam_backend.github.activity;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.wardk.meeteam_backend.domain.github.activity.*;
import com.wardk.meeteam_backend.domain.github.integration.*;
import com.wardk.meeteam_backend.domain.github.repository.GithubAppClient;
import jakarta.persistence.EntityManager;
import org.junit.jupiter.api.Test;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.SimpleTransactionStatus;
import java.time.Clock;
import java.time.Instant;
import java.util.*;
import jakarta.persistence.*;
import static org.mockito.Mockito.*;
import static org.assertj.core.api.Assertions.*;
class GithubActivitySyncTest {
 private final EntityManager em=mock(EntityManager.class);private final GithubAppClient client=mock(GithubAppClient.class);private final PlatformTransactionManager manager=mock(PlatformTransactionManager.class);private final GithubActivityWriter writer=mock(GithubActivityWriter.class);
 private GithubActivitySync sync(){when(manager.getTransaction(any())).thenAnswer(i->new SimpleTransactionStatus());return new GithubActivitySync(em,client,writer,new ObjectMapper(),Clock.systemUTC(),manager);}
 private GithubProjectLink link(){var l=new GithubProjectLink(1);l.setInstallationId(2L);l.setInstallationActive(true);l.setGithubRepositoryId(3L);l.setBindingVersion(4);return l;}
 @Test void pendingMetadataThrowsForDurableRetryWithoutChangingSnapshot(){when(em.find(GithubProjectLink.class,1L)).thenReturn(link());when(client.request(2,"GET","/repositories/3",null)).thenReturn(new GithubAppClient.Reply(202,new ObjectMapper().nullNode()));assertThatThrownBy(()->sync().handle(new GithubWorkHandler.Job(1,"SYNC",1L,null,4,"{}"))).isInstanceOf(IllegalStateException.class).hasMessageContaining("retry");verify(em,never()).persist(any());verifyNoInteractions(writer);}
 @Test void outdatedBindingSkipsAllNetworkAndWrites(){when(em.find(GithubProjectLink.class,1L)).thenReturn(link());sync().handle(new GithubWorkHandler.Job(1,"SYNC",1L,null,3,"{}"));verifyNoInteractions(client,writer);verify(em,never()).persist(any());}
 @Test void unlinkedProjectSkipsNetwork(){when(em.find(GithubProjectLink.class,1L)).thenReturn(new GithubProjectLink(1));sync().handle(new GithubWorkHandler.Job(1,"SYNC",1L,null,0,"{}"));verifyNoInteractions(client,writer);}
 private void emptyResponses() throws Exception {var mapper=new ObjectMapper();when(client.request(2,"GET","/repositories/3",null)).thenReturn(new GithubAppClient.Reply(200,mapper.readTree("{\"id\":3,\"full_name\":\"owner/repo\",\"html_url\":\"https://github.com/owner/repo\",\"size\":0,\"default_branch\":\"feature/main\",\"private\":false,\"owner\":{\"login\":\"owner\"},\"name\":\"repo\"}")));when(client.request(2,"GET","/repos/owner/repo/commits?sha=feature%2Fmain",null)).thenReturn(new GithubAppClient.Reply(404,mapper.nullNode()));when(client.request(2,"GET","/repos/owner/repo/languages",null)).thenReturn(new GithubAppClient.Reply(200,mapper.createObjectNode()));when(client.paginate(eq(2L),anyString(),isNull())).thenReturn(List.of());when(client.graphQL(eq(2L),anyString(),anyMap())).thenReturn(mapper.readTree("{\"repository\":{\"pullRequests\":{\"nodes\":[],\"pageInfo\":{\"hasNextPage\":false}}}}"));}
 @Test @SuppressWarnings("unchecked") void confirmedEmptyRepositoryGetsValidDormantSnapshotUsingSlashBranchQuery() throws Exception {var l=link();when(em.find(GithubProjectLink.class,1L)).thenReturn(l);when(em.find(GithubProjectLink.class,1L,LockModeType.PESSIMISTIC_WRITE)).thenReturn(l);emptyResponses();TypedQuery<GithubPullRequest> prs=mock(TypedQuery.class);when(em.createQuery(anyString(),eq(GithubPullRequest.class))).thenReturn(prs);when(prs.setParameter(anyString(),any())).thenReturn(prs);when(prs.getResultList()).thenReturn(List.of());sync().handle(new GithubWorkHandler.Job(1,"SYNC",1L,null,4,"{}"));var capture=org.mockito.ArgumentCaptor.forClass(GithubRepositorySnapshot.class);verify(em).persist(capture.capture());assertThat(capture.getValue().getLastPushedAt()).isNull();assertThat(capture.getValue().getSyncedAt()).isNotNull();assertThat(capture.getValue().getWeeklyCounts()).isEqualTo("[0,0,0,0,0,0,0,0]");verify(client,never()).request(eq(2L),eq("GET"),contains("/branches/"),isNull());}
 @Test void newerPrivatizationFencesStaleNetworkApply() throws Exception {var l=link();l.setRepositoryPrivate(true);when(em.find(GithubProjectLink.class,1L)).thenReturn(l);when(em.find(GithubProjectLink.class,1L,LockModeType.PESSIMISTIC_WRITE)).thenReturn(l);doAnswer(i->{l.setRowVersion(1);return null;}).when(em).refresh(l,LockModeType.PESSIMISTIC_WRITE);emptyResponses();assertThatThrownBy(()->sync().handle(new GithubWorkHandler.Job(1,"SYNC",1L,null,4,"{}"))).isInstanceOf(IllegalStateException.class).hasMessageContaining("changed");assertThat(l.isRepositoryPrivate()).isTrue();verify(em,never()).persist(any());verifyNoInteractions(writer);}
 @Test void reconciliationNeverClosesPresentOrNewerWebhookRows(){Instant start=Instant.parse("2026-11-05T00:00:00Z");assertThat(GithubActivityRules.mayCloseAbsent(1,start.minusSeconds(10),Set.of(1),start)).isFalse();assertThat(GithubActivityRules.mayCloseAbsent(2,start.plusSeconds(1),Set.of(1),start)).isFalse();assertThat(GithubActivityRules.mayCloseAbsent(2,start.minusSeconds(10),Set.of(1),start)).isTrue();}

 @Test void rejectsOversizedMetadataBeforeFollowupRequests() throws Exception {var l=link();when(em.find(GithubProjectLink.class,1L)).thenReturn(l);var repo=new ObjectMapper().createObjectNode();repo.put("id",3);repo.put("full_name","owner/repo");repo.put("html_url","https://github.com/owner/repo");repo.put("default_branch","main");repo.put("description","x".repeat(501));when(client.request(2,"GET","/repositories/3",null)).thenReturn(new GithubAppClient.Reply(200,repo));assertThatThrownBy(()->sync().handle(new GithubWorkHandler.Job(1,"SYNC",1L,null,4,"{}"))).isInstanceOf(IllegalStateException.class).hasMessageContaining("Invalid");verify(client,times(1)).request(anyLong(),anyString(),anyString(),any());verifyNoInteractions(writer);}
}
